package com.mycompany.projetmedical.dao;

import com.mycompany.projetmedical.util.Bdd;
import com.mycompany.projetmedical.util.Journal;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.sql.*;
import java.time.LocalDate;
import java.util.*;

/** Accès à la facturation et aux paiements, avec calcul et verrouillage côté PostgreSQL. */
public class CaisseDao {
    public record Stats(long facturesOuvertes,long impayees,long partielles,BigDecimal resteDu,BigDecimal encaisseAujourdhui,BigDecimal facturesAujourdhui){}
    public record Patient(int id,String numero,String nom,String telephone){}
    public record Prestation(int id,String code,String libelle,BigDecimal prix){}
    public record Ligne(long id,String libelle,BigDecimal quantite,BigDecimal prix,BigDecimal montant){}
    public record Facture(long id,String numero,int patientId,String numeroPatient,String patient,LocalDate date,LocalDate echeance,String statut,BigDecimal total,BigDecimal paye,BigDecimal restant,String notes,List<Ligne> lignes){}
    public record Paiement(long id,long factureId,String numeroFacture,String numeroPatient,String patient,BigDecimal montant,String mode,Timestamp date,String reference,String notes,String encaisseur,BigDecimal totalFacture,BigDecimal solde){}
    public record Rapport(LocalDate jour,long nombre,BigDecimal encaisse){}

    public Stats stats()throws SQLException{
        String q="SELECT count(*) FILTER(WHERE statut IN ('EN_ATTENTE','PARTIELLEMENT_PAYEE')),count(*) FILTER(WHERE statut='EN_ATTENTE'),count(*) FILTER(WHERE statut='PARTIELLEMENT_PAYEE'),coalesce(sum(montant_restant) FILTER(WHERE statut IN ('EN_ATTENTE','PARTIELLEMENT_PAYEE')),0),coalesce((SELECT sum(montant) FROM paiements WHERE date_paiement::date=CURRENT_DATE),0),coalesce(sum(montant_total) FILTER(WHERE date_facture=CURRENT_DATE),0) FROM factures";
        try(Connection c=Bdd.connexion();PreparedStatement p=c.prepareStatement(q);ResultSet r=p.executeQuery()){r.next();return new Stats(r.getLong(1),r.getLong(2),r.getLong(3),r.getBigDecimal(4),r.getBigDecimal(5),r.getBigDecimal(6));}
    }
    public List<Patient> patients(String q)throws SQLException{
        String sql="SELECT p.utilisateur_id,p.numero_dossier,u.prenoms||' '||u.nom,u.telephone FROM patients p JOIN utilisateurs u ON u.id=p.utilisateur_id WHERE (?='' OR p.numero_dossier ILIKE ? OR u.nom ILIKE ? OR u.prenoms ILIKE ? OR coalesce(u.telephone,'') ILIKE ?) ORDER BY u.nom,u.prenoms LIMIT 200";String v=q==null?"":q.trim(),like="%"+v+"%";
        try(Connection c=Bdd.connexion();PreparedStatement p=c.prepareStatement(sql)){p.setString(1,v);for(int i=2;i<=5;i++)p.setString(i,like);try(ResultSet r=p.executeQuery()){List<Patient>a=new ArrayList<>();while(r.next())a.add(new Patient(r.getInt(1),r.getString(2),r.getString(3),r.getString(4)));return a;}}
    }
    public Patient patient(int id)throws SQLException{try(Connection c=Bdd.connexion();PreparedStatement p=c.prepareStatement("SELECT p.utilisateur_id,p.numero_dossier,u.prenoms||' '||u.nom,u.telephone FROM patients p JOIN utilisateurs u ON u.id=p.utilisateur_id WHERE p.utilisateur_id=?")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){return r.next()?new Patient(r.getInt(1),r.getString(2),r.getString(3),r.getString(4)):null;}}}
    public List<Prestation> prestations()throws SQLException{try(Connection c=Bdd.connexion();PreparedStatement p=c.prepareStatement("SELECT id,code,libelle,prix_unitaire FROM prestations WHERE actif=true ORDER BY categorie,libelle");ResultSet r=p.executeQuery()){List<Prestation>a=new ArrayList<>();while(r.next())a.add(new Prestation(r.getInt(1),r.getString(2),r.getString(3),r.getBigDecimal(4)));return a;}}
    private static String FACTURE_SELECT="SELECT f.id,f.numero_facture,f.patient_id,p.numero_dossier,u.prenoms||' '||u.nom patient,f.date_facture,f.echeance,f.statut,f.montant_total,f.montant_paye,f.montant_restant,f.notes FROM factures f JOIN patients p ON p.utilisateur_id=f.patient_id JOIN utilisateurs u ON u.id=p.utilisateur_id ";
    public List<Facture> factures(String q,String statut,boolean impayees)throws SQLException{
        StringBuilder sql=new StringBuilder(FACTURE_SELECT+"WHERE 1=1 ");List<Object> params=new ArrayList<>();if(impayees)sql.append("AND f.statut IN ('EN_ATTENTE','PARTIELLEMENT_PAYEE') ");if(statut!=null&&!statut.isBlank()){sql.append("AND f.statut=? ");params.add(statut);}if(q!=null&&!q.isBlank()){sql.append("AND (f.numero_facture ILIKE ? OR p.numero_dossier ILIKE ? OR u.nom ILIKE ? OR u.prenoms ILIKE ?) ");String like="%"+q.trim()+"%";params.add(like);params.add(like);params.add(like);params.add(like);}sql.append("ORDER BY f.date_facture DESC,f.id DESC LIMIT 500");
        try(Connection c=Bdd.connexion();PreparedStatement p=c.prepareStatement(sql.toString())){for(int i=0;i<params.size();i++)p.setObject(i+1,params.get(i));try(ResultSet r=p.executeQuery()){List<Facture>a=new ArrayList<>();while(r.next())a.add(facture(r,List.of()));return a;}}
    }
    public List<Facture> facturesPatient(int patientId)throws SQLException{String q=FACTURE_SELECT+"WHERE f.patient_id=? ORDER BY f.date_facture DESC,f.id DESC";try(Connection c=Bdd.connexion();PreparedStatement p=c.prepareStatement(q)){p.setInt(1,patientId);try(ResultSet r=p.executeQuery()){List<Facture>a=new ArrayList<>();while(r.next())a.add(facture(r,List.of()));return a;}}}
    public Facture facture(long id)throws SQLException{try(Connection c=Bdd.connexion();PreparedStatement p=c.prepareStatement(FACTURE_SELECT+"WHERE f.id=?")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){if(!r.next())return null;Facture f=facture(r,lignes(id));return f;}}}
    private Facture facture(ResultSet r,List<Ligne> lignes)throws SQLException{java.sql.Date e=r.getDate("echeance");return new Facture(r.getLong("id"),r.getString("numero_facture"),r.getInt("patient_id"),r.getString("numero_dossier"),r.getString("patient"),r.getDate("date_facture").toLocalDate(),e==null?null:e.toLocalDate(),r.getString("statut"),r.getBigDecimal("montant_total"),r.getBigDecimal("montant_paye"),r.getBigDecimal("montant_restant"),r.getString("notes"),lignes);}
    public List<Ligne> lignes(long id)throws SQLException{try(Connection c=Bdd.connexion();PreparedStatement p=c.prepareStatement("SELECT id,libelle,quantite,prix_unitaire,montant_ligne FROM lignes_facture WHERE facture_id=? ORDER BY id")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){List<Ligne>a=new ArrayList<>();while(r.next())a.add(new Ligne(r.getLong(1),r.getString(2),r.getBigDecimal(3),r.getBigDecimal(4),r.getBigDecimal(5)));return a;}}}
    public long creerFacture(int patient,List<Integer> prestationIds,List<BigDecimal> quantites,String notes,LocalDate echeance,long caisse,String ip)throws SQLException{
        if(prestationIds.isEmpty()||prestationIds.size()!=quantites.size())throw new IllegalArgumentException("Ajoutez au moins une ligne de prestation.");
        try(Connection c=Bdd.connexion()){c.setAutoCommit(false);try{
            String numero="FAC-"+LocalDate.now().toString().replace("-","")+"-"+UUID.randomUUID().toString().substring(0,8).toUpperCase();long id;
            try(PreparedStatement p=c.prepareStatement("INSERT INTO factures(numero_facture,patient_id,echeance,notes,cree_par) SELECT ?,p.utilisateur_id,?,?,? FROM patients p JOIN utilisateurs u ON u.id=p.utilisateur_id WHERE p.utilisateur_id=? AND u.role_code='PATIENT' RETURNING id")){p.setString(1,numero);if(echeance==null)p.setNull(2,Types.DATE);else p.setDate(2,java.sql.Date.valueOf(echeance));p.setString(3,notes);p.setLong(4,caisse);p.setInt(5,patient);try(ResultSet r=p.executeQuery()){if(!r.next())throw new SQLException("Patient introuvable.","02000");id=r.getLong(1);}}
            BigDecimal total=BigDecimal.ZERO.setScale(2);for(int i=0;i<prestationIds.size();i++){
                BigDecimal qty=quantites.get(i).setScale(2,RoundingMode.HALF_UP);if(qty.signum()<=0)throw new IllegalArgumentException("La quantité doit être supérieure à zéro.");
                try(PreparedStatement p=c.prepareStatement("SELECT libelle,prix_unitaire FROM prestations WHERE id=? AND actif=true FOR SHARE")){p.setInt(1,prestationIds.get(i));try(ResultSet r=p.executeQuery()){if(!r.next())throw new SQLException("Prestation inactive ou inexistante.","02000");String lib=r.getString(1);BigDecimal price=r.getBigDecimal(2).setScale(2,RoundingMode.HALF_UP);BigDecimal line=price.multiply(qty).setScale(2,RoundingMode.HALF_UP);try(PreparedStatement ins=c.prepareStatement("INSERT INTO lignes_facture(facture_id,prestation_id,libelle,quantite,prix_unitaire,montant_ligne) VALUES(?,?,?,?,?,?)")){ins.setLong(1,id);ins.setInt(2,prestationIds.get(i));ins.setString(3,lib);ins.setBigDecimal(4,qty);ins.setBigDecimal(5,price);ins.setBigDecimal(6,line);ins.executeUpdate();}total=total.add(line);}}
            }
            try(PreparedStatement p=c.prepareStatement("UPDATE factures SET montant_total=?,montant_restant=?,date_modification=now() WHERE id=?")){p.setBigDecimal(1,total);p.setBigDecimal(2,total);p.setLong(3,id);p.executeUpdate();}
            Journal.ecrire(c,caisse,Journal.CREATION_FACTURE,"factures",id,"Création de facture",true,ip);c.commit();return id;
        }catch(SQLException|RuntimeException e){c.rollback();throw e;}finally{c.setAutoCommit(true);}}
    }
    public long payer(long facture,BigDecimal montant,String mode,String reference,String notes,long caisse,String ip)throws SQLException{
        BigDecimal valeur=montant.setScale(2,RoundingMode.HALF_UP);if(valeur.signum()<=0)throw new IllegalArgumentException("Le paiement doit être supérieur à zéro.");
        try(Connection c=Bdd.connexion()){c.setAutoCommit(false);try{
            BigDecimal total;String statut;try(PreparedStatement p=c.prepareStatement("SELECT montant_total,statut FROM factures WHERE id=? FOR UPDATE")){p.setLong(1,facture);try(ResultSet r=p.executeQuery()){if(!r.next())throw new SQLException("Facture introuvable.","02000");total=r.getBigDecimal(1);statut=r.getString(2);}}
            if("ANNULEE".equals(statut)||"PAYEE".equals(statut))throw new SQLException("Facture annulée ou déjà payée.","23514");BigDecimal deja;try(PreparedStatement p=c.prepareStatement("SELECT coalesce(sum(montant),0) FROM paiements WHERE facture_id=?")){p.setLong(1,facture);try(ResultSet r=p.executeQuery()){r.next();deja=r.getBigDecimal(1);}}
            BigDecimal restant=total.subtract(deja).setScale(2,RoundingMode.HALF_UP);if(valeur.compareTo(restant)>0)throw new IllegalArgumentException("Le paiement dépasse le solde restant de "+restant+".");long pid;
            try(PreparedStatement p=c.prepareStatement("INSERT INTO paiements(facture_id,montant,mode_paiement,reference,notes,encaisse_par) VALUES(?,?,?,?,?,?) RETURNING id")){p.setLong(1,facture);p.setBigDecimal(2,valeur);p.setString(3,mode);p.setString(4,reference);p.setString(5,notes);p.setLong(6,caisse);try(ResultSet r=p.executeQuery()){r.next();pid=r.getLong(1);}}
            BigDecimal paye=deja.add(valeur).setScale(2,RoundingMode.HALF_UP),reste=total.subtract(paye).setScale(2,RoundingMode.HALF_UP);String newStatus=reste.signum()==0?"PAYEE":"PARTIELLEMENT_PAYEE";
            try(PreparedStatement p=c.prepareStatement("UPDATE factures SET montant_paye=?,montant_restant=?,statut=?,date_modification=now() WHERE id=?")){p.setBigDecimal(1,paye);p.setBigDecimal(2,reste);p.setString(3,newStatus);p.setLong(4,facture);p.executeUpdate();}
            Journal.ecrire(c,caisse,Journal.ENCAISSEMENT,"paiements",pid,"Paiement confirmé et solde de facture recalculé",true,ip);c.commit();return pid;
        }catch(SQLException|RuntimeException e){c.rollback();throw e;}finally{c.setAutoCommit(true);}}
    }
    public List<Paiement> paiements(String q,LocalDate du,LocalDate au)throws SQLException{
        String sql="SELECT p.id,p.facture_id,f.numero_facture,pa.numero_dossier,pu.prenoms||' '||pu.nom patient,p.montant,p.mode_paiement,p.date_paiement,p.reference,p.notes,coalesce(ca.prenoms||' '||ca.nom,''),f.montant_total,f.montant_total-(SELECT coalesce(sum(p2.montant),0) FROM paiements p2 WHERE p2.facture_id=f.id AND (p2.date_paiement<p.date_paiement OR (p2.date_paiement=p.date_paiement AND p2.id<=p.id))) solde FROM paiements p JOIN factures f ON f.id=p.facture_id JOIN patients pa ON pa.utilisateur_id=f.patient_id JOIN utilisateurs pu ON pu.id=pa.utilisateur_id LEFT JOIN utilisateurs ca ON ca.id=p.encaisse_par WHERE p.date_paiement::date BETWEEN ? AND ? AND (?='' OR f.numero_facture ILIKE ? OR pa.numero_dossier ILIKE ? OR pu.nom ILIKE ?) ORDER BY p.date_paiement DESC LIMIT 1000";
        String needle=q==null?"":q.trim(),like="%"+needle+"%";try(Connection c=Bdd.connexion();PreparedStatement p=c.prepareStatement(sql)){p.setDate(1,java.sql.Date.valueOf(du));p.setDate(2,java.sql.Date.valueOf(au));p.setString(3,needle);for(int i=4;i<=6;i++)p.setString(i,like);try(ResultSet r=p.executeQuery()){List<Paiement>a=new ArrayList<>();while(r.next())a.add(new Paiement(r.getLong(1),r.getLong(2),r.getString(3),r.getString(4),r.getString(5),r.getBigDecimal(6),r.getString(7),r.getTimestamp(8),r.getString(9),r.getString(10),r.getString(11),r.getBigDecimal(12),r.getBigDecimal(13)));return a;}}
    }
    public List<Paiement> paiementsFacture(long id)throws SQLException{String q="SELECT p.id,p.facture_id,f.numero_facture,pa.numero_dossier,pu.prenoms||' '||pu.nom patient,p.montant,p.mode_paiement,p.date_paiement,p.reference,p.notes,coalesce(ca.prenoms||' '||ca.nom,''),f.montant_total,f.montant_total-(SELECT coalesce(sum(p2.montant),0) FROM paiements p2 WHERE p2.facture_id=f.id AND (p2.date_paiement<p.date_paiement OR (p2.date_paiement=p.date_paiement AND p2.id<=p.id))) solde FROM paiements p JOIN factures f ON f.id=p.facture_id JOIN patients pa ON pa.utilisateur_id=f.patient_id JOIN utilisateurs pu ON pu.id=pa.utilisateur_id LEFT JOIN utilisateurs ca ON ca.id=p.encaisse_par WHERE p.facture_id=? ORDER BY p.date_paiement DESC";try(Connection c=Bdd.connexion();PreparedStatement p=c.prepareStatement(q)){p.setLong(1,id);try(ResultSet r=p.executeQuery()){List<Paiement>a=new ArrayList<>();while(r.next())a.add(paiement(r));return a;}}}
    public Paiement paiement(long id)throws SQLException{String q="SELECT p.id,p.facture_id,f.numero_facture,pa.numero_dossier,pu.prenoms||' '||pu.nom patient,p.montant,p.mode_paiement,p.date_paiement,p.reference,p.notes,coalesce(ca.prenoms||' '||ca.nom,''),f.montant_total,f.montant_total-(SELECT coalesce(sum(p2.montant),0) FROM paiements p2 WHERE p2.facture_id=f.id AND (p2.date_paiement<p.date_paiement OR (p2.date_paiement=p.date_paiement AND p2.id<=p.id))) solde FROM paiements p JOIN factures f ON f.id=p.facture_id JOIN patients pa ON pa.utilisateur_id=f.patient_id JOIN utilisateurs pu ON pu.id=pa.utilisateur_id LEFT JOIN utilisateurs ca ON ca.id=p.encaisse_par WHERE p.id=?";try(Connection c=Bdd.connexion();PreparedStatement p=c.prepareStatement(q)){p.setLong(1,id);try(ResultSet r=p.executeQuery()){return r.next()?paiement(r):null;}}}
    private Paiement paiement(ResultSet r)throws SQLException{return new Paiement(r.getLong(1),r.getLong(2),r.getString(3),r.getString(4),r.getString(5),r.getBigDecimal(6),r.getString(7),r.getTimestamp(8),r.getString(9),r.getString(10),r.getString(11),r.getBigDecimal(12),r.getBigDecimal(13));}
    public List<Rapport> rapport(LocalDate du,LocalDate au)throws SQLException{String q="SELECT date_paiement::date,count(*),sum(montant) FROM paiements WHERE date_paiement::date BETWEEN ? AND ? GROUP BY 1 ORDER BY 1";try(Connection c=Bdd.connexion();PreparedStatement p=c.prepareStatement(q)){p.setDate(1,java.sql.Date.valueOf(du));p.setDate(2,java.sql.Date.valueOf(au));try(ResultSet r=p.executeQuery()){List<Rapport>a=new ArrayList<>();while(r.next())a.add(new Rapport(r.getDate(1).toLocalDate(),r.getLong(2),r.getBigDecimal(3)));return a;}}}
}
